import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));describe("Muziris Ancient Port Explorer Tests",()=>{it("HTML contains historical overview, location, timeline, trade, and discoveries",()=>{const e=readFileSync(resolve(__dirname,"../../muziris-port-explorer/index.html"),"utf-8");expect(e).toContain('id="overview"'),expect(e).toContain('id="location-timeline"'),expect(e).toContain('id="trade-significance"'),expect(e).toContain('id="discoveries"'),expect(e).toContain('id="gallery"'),expect(e).toContain('id="references"'),expect(e).toContain("Muziris"),expect(e).toContain("Chera"),expect(e).toContain("Pattanam")}),it("CSS stylesheet exists and defines port styling tokens",()=>{const e=readFileSync(resolve(__dirname,"../../muziris-port-explorer/style.css"),"utf-8");expect(e).toContain("--port-teal"),expect(e).toContain(".port-main"),expect(e).toContain(".port-hero")}),it("JavaScript module initializes cleanly",()=>{const e=readFileSync(resolve(__dirname,"../../muziris-port-explorer/script.js"),"utf-8");expect(e).toContain("MuzirisPortExplorer"),expect(e).toContain("setupGalleryModal")})});